fn admit_source_issuer<T>(cx:&mut StepContext<'_>,slot:&mut Option<T>,accepted:&mut bool,binding:&mut Option<OriginalSourceBinding>,identity:OriginalSourceBinding,bytes:usize,create:impl FnOnce()->T)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.should_yield()||cx.is_cancelled()||cx.fuel_remaining()==0||grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<bytes{return Ok(false)}*slot=Some(create());*binding=Some(identity);let receipt=cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()});cx.consume_fuel(1);receipt?;*accepted=true;Ok(true)}
fn encoding_refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
